using System.Diagnostics;
using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using AeppGenerator.Api.Auth;
using AeppGenerator.Api.Controllers;
using AeppGenerator.Api.Data;
using AeppGenerator.Api.Gamification;
using Microsoft.Data.Sqlite;
using Microsoft.AspNetCore.Hosting.Server;
using Microsoft.AspNetCore.Hosting.Server.Features;

var folder=Path.Combine(Path.GetTempPath(),"aepp-progress-"+Guid.NewGuid());Directory.CreateDirectory(folder);
int checks=0;void Check(bool yes,string label){if(!yes)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
var json=new JsonSerializerOptions(JsonSerializerDefaults.Web);
JsonNode Node(object value)=>JsonSerializer.SerializeToNode(value,json)!;
var legacyPath=Path.Combine(folder,"legacy.sqlite");
using(var legacy=new SqliteConnection("Data Source="+legacyPath)){legacy.Open();using var cmd=legacy.CreateCommand();cmd.CommandText="""
CREATE TABLE Users(Id TEXT PRIMARY KEY,Email TEXT NOT NULL,NormalizedEmail TEXT NOT NULL UNIQUE,PasswordHash TEXT NOT NULL,FullName TEXT NOT NULL,Role TEXT NOT NULL,CreatedAt TEXT NOT NULL);
CREATE TABLE UserProgress(UserId TEXT PRIMARY KEY REFERENCES Users(Id),TotalXP INTEGER NOT NULL DEFAULT 0,CurrentStreak INTEGER NOT NULL DEFAULT 0,MaxStreak INTEGER NOT NULL DEFAULT 0,LastChallengeDate TEXT,Badges TEXT NOT NULL DEFAULT '[]',ProfileJson TEXT NOT NULL);
INSERT INTO Users VALUES('legacy','legacy@example.test','LEGACY@EXAMPLE.TEST','hash','Παλαιός μαθητής','STUDENT','2026-01-01');
""";cmd.ExecuteNonQuery();var p=new StudentProfile{Id="legacy",PublicCode="legacy-code",Username="Παλιός",Group="A",Completions=[new(){Day="2026-10-07",StartedAt=DateTimeOffset.Parse("2026-10-07T10:00:00Z"),CompletedAt=DateTimeOffset.Parse("2026-10-07T10:02:00Z"),Xp=130,Streak=1,LoopResults=[true,true]}],Freezes=["2026-10-08"],Studies=["2026-10-08"],Badges=["first"]};cmd.CommandText="INSERT INTO UserProgress VALUES('legacy',999,1,1,'2026-10-07','[\"first\"]',$json)";cmd.Parameters.AddWithValue("$json",JsonSerializer.Serialize(p,json));cmd.ExecuteNonQuery();}
var migrated=new AccountStore(legacyPath);Check(migrated.Progress("legacy").TotalXP==130,"legacy migration imports completion once and rebuilds XP");
var restored=new AccountStore(legacyPath);Check(restored.Progress("legacy").TotalXP==130,"migration restart does not duplicate XP");
using(var c=new SqliteConnection(restored.ConnectionString)){c.Open();using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*) FROM pragma_table_info('UserProgress') WHERE name='ProfileJson'";Check(Convert.ToInt32(cmd.ExecuteScalar())==0,"ProfileJson column physically removed");cmd.CommandText="SELECT COUNT(*) FROM ChallengeFreezes";Check(Convert.ToInt32(cmd.ExecuteScalar())==1,"freeze history preserved");}
var clock=new TestClock{Time=DateTimeOffset.Parse("2026-10-08T10:00:00Z")};
var builder=WebApplication.CreateBuilder(args);builder.Logging.ClearProviders();builder.Configuration["Accounts:DatabasePath"]=Path.Combine(folder,"accounts.sqlite");builder.Configuration["Auth:SigningKey"]=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));builder.WebHost.UseUrls("http://127.0.0.1:0");builder.AddAccounts();builder.Services.AddSingleton(services=>new GamificationService(Path.Combine(folder,"unused.json"),clock,services.GetRequiredService<AccountStore>()));builder.Services.AddControllers().AddApplicationPart(typeof(LeaderboardController).Assembly);
await using var app=builder.Build();var store=app.Services.GetRequiredService<AccountStore>();var game=app.Services.GetRequiredService<GamificationService>();app.UseDeveloperExceptionPage();app.UseRouting();app.UseAccountOriginGuard();app.UseAuthentication();app.UseAuthorization();app.MapControllers();
var user=await store.Register("student@example.test","hash","Μαθητής");var other=await store.Register("other@example.test","hash","Άλλος");
using var stream=typeof(GamificationService).Assembly.GetManifestResourceStream("AeppGenerator.DailyChallengeBank")!;var packs=JsonNode.Parse(stream)!["packs"]!.AsArray();
JsonNode Pack(string day){var n=(int)(DateTime.Parse(day)-DateTime.UnixEpoch).TotalDays;return packs[((n%packs.Count)+packs.Count)%packs.Count]!;}
Dictionary<string,string> Answers(string day)=>Pack(day)["questions"]!.AsArray().SelectMany(q=>q!["kind"]!.GetValue<string>()=="fill"?q["blanks"]!.AsArray().Select(b=>KeyValuePair.Create(q["id"]!.GetValue<string>()+":"+b!["id"]!.GetValue<string>(),b["accepted"]![0]!.GetValue<string>())):[KeyValuePair.Create(q["id"]!.GetValue<string>(),q["answer"]!.GetValue<string>())]).ToDictionary();
async Task<JsonNode> Finish(string id,string day){clock.Time=DateTimeOffset.Parse(day+"T10:00:00Z");await game.Start(id);await game.Theory(id,day,Pack(day)["questions"]![0]!["answer"]!.GetValue<string>());clock.Time=clock.Time.AddSeconds(120);return Node(await game.Complete(id,day,Answers(day)));}
await game.Start(user.Id);await game.Theory(user.Id,game.Day,Pack(game.Day)["questions"]![0]!["answer"]!.GetValue<string>());
List<string> commands=[];store.ObserveCommand=commands.Add;var completed=Node(await game.Complete(user.Id,game.Day,Answers(game.Day)));store.ObserveCommand=null;
Check(completed["xp"]!.GetValue<int>()==130 && completed["streak"]!.GetValue<int>()==1,"completion awards XP and streak");Check(commands.Count(sql=>sql.StartsWith("UPDATE UserProgress"))==1,"XP and streak updated by exactly one DB command");Check(commands.Where(sql=>sql.StartsWith("SELECT")).All(sql=>sql.Contains("WHERE UserId=$id")),"completion reads only current user and bounded history");
await Task.WhenAll(Enumerable.Range(0,12).Select(_=>Task.Run(()=>game.Complete(user.Id,game.Day,Answers(game.Day)))));Check(store.Progress(user.Id).TotalXP==130,"concurrent completion retries award exactly once");
await Finish(user.Id,"2026-10-09");clock.Time=DateTimeOffset.Parse("2026-10-10T10:00:00Z");await game.Study(user.Id,"lesson-1");await game.Freeze(user.Id);Check(Node(await game.Get(user.Id))["streak"]!.GetValue<int>()==2,"freeze preserves streak without increment");Check((await Finish(user.Id,"2026-10-11"))["streak"]!.GetValue<int>()==3,"freeze bridges a missed day");
commands.Clear();store.ObserveCommand=commands.Add;await game.Get(user.Id);store.ObserveCommand=null;Check(commands.All(sql=>!sql.StartsWith("UPDATE")&&!sql.StartsWith("INSERT")),"GET progress issues no writes");Check(Node(await game.Get(user.Id))["profile"]!["completions"]!.AsArray().Count==1,"profile API contains only today's completion");
clock.Time=DateTimeOffset.Parse("2026-10-13T10:00:00Z");Check(Node(await game.Get(user.Id))["streak"]!.GetValue<int>()==0,"expired streak computed without history scan");Check((await Finish(user.Id,"2026-10-13"))["streak"]!.GetValue<int>()==1,"gap starts new streak");
await game.Update(user.Id,"Μαθητής","🦉","A",[]);await game.Update(other.Id,"Άλλος","🐢","A",[]);var otherCode=Node(await game.Get(other.Id))["profile"]!["publicCode"]!.GetValue<string>();await game.Update(user.Id,"Μαθητής","🦉","A",[otherCode]);Check((await game.RankingPage(user.Id,"all","friends",1,20)).Items.Count==2,"SQL friends filter preserved");Check((await game.RankingPage(user.Id,"all","group",1,20)).Items.Count==2,"SQL group filter preserved");
using(var c=new SqliteConnection(store.ConnectionString)){c.Open();using var tx=c.BeginTransaction();using var add=c.CreateCommand();add.Transaction=tx;add.CommandText="INSERT INTO Users VALUES($id,$email,$email,'hash','Μαθητής φορτίου','STUDENT','2026-10-01'); INSERT INTO UserProgress(UserId,PublicCode,Username,TotalXP,CurrentStreak,LastActivityDate) VALUES($id,$id,'Μαθητής φορτίου',$xp,$streak,'2026-10-13')";add.Parameters.AddWithValue("$id","");add.Parameters.AddWithValue("$email","");add.Parameters.AddWithValue("$xp",0);add.Parameters.AddWithValue("$streak",0);for(var i=0;i<10000;i++){add.Parameters["$id"].Value="load-"+i.ToString("D5");add.Parameters["$email"].Value="load"+i+"@example.test";add.Parameters["$xp"].Value=i/2;add.Parameters["$streak"].Value=i%2;add.ExecuteNonQuery();}tx.Commit();using var plan=c.CreateCommand();plan.CommandText="EXPLAIN QUERY PLAN "+AccountStore.NationalLeaderboardSql;plan.Parameters.AddWithValue("$day",game.Day);plan.Parameters.AddWithValue("$yesterday","2026-10-12");plan.Parameters.AddWithValue("$limit",21);plan.Parameters.AddWithValue("$offset",0);using var r=plan.ExecuteReader();List<string> steps=[];while(r.Read())steps.Add(r.GetString(3));Check(steps.Any(step=>step.Contains("IX_Progress_Ranking")),"leaderboard uses XP ranking index");}
await app.StartAsync();using var http=new HttpClient{BaseAddress=new Uri(app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single())};
Check((await http.GetAsync("/api/leaderboard")).StatusCode==HttpStatusCode.Unauthorized,"leaderboard requires authentication");var token=JsonSerializer.SerializeToElement(app.Services.GetRequiredService<AuthService>().Issue(user,new DefaultHttpContext().Response,false)).GetProperty("token").GetString();http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);
var warm=await http.GetFromJsonAsync<LeaderboardPage>("/api/leaderboard?page=1&pageSize=20");commands.Clear();store.ObserveCommand=commands.Add;var timer=Stopwatch.StartNew();var page1=await http.GetFromJsonAsync<LeaderboardPage>("/api/leaderboard?page=1&pageSize=20");timer.Stop();store.ObserveCommand=null;
Check(page1!.Items.Count==20&&page1.HasNextPage,"HTTP page size bounded to 20 of 10002 users");Check(commands.Count(sql=>sql==AccountStore.NationalLeaderboardSql)==1 && commands.All(sql=>!sql.Contains("ResultJson")&&!sql.Contains("ProfileJson")),"HTTP leaderboard reads one scalar SQL page without profiles or completions");var page2=await http.GetFromJsonAsync<LeaderboardPage>("/api/leaderboard?page=2&pageSize=20");Check(!page1.Items.Select(x=>x.UserId).Intersect(page2!.Items.Select(x=>x.UserId)).Any()&&page2.Items.First().Rank==21,"stable pages without duplicate users");Check(page1.Items.Zip(page1.Items.Skip(1)).All(pair=>pair.First.TotalXP>pair.Second.TotalXP||pair.First.TotalXP==pair.Second.TotalXP&&pair.First.CurrentStreak>=pair.Second.CurrentStreak),"XP and streak tie-break ordering");Check((await http.GetAsync("/api/leaderboard?pageSize=5000")).StatusCode==HttpStatusCode.BadRequest,"oversized page rejected");Check((await http.GetAsync("/api/leaderboard?page=2147483647")).StatusCode==HttpStatusCode.BadRequest,"overflow page rejected");
Console.WriteLine($"Leaderboard HTTP page: {timer.Elapsed.TotalMilliseconds:F2} ms / 10002 users.");Console.WriteLine(checks+" progress checks passed.");await app.StopAsync();
sealed class TestClock:TimeProvider{public DateTimeOffset Time{get;set;}public override DateTimeOffset GetUtcNow()=>Time;}
